(5132610, 747137, 100393, '<td valign="top">I like the colours on this shot.</td>', 'I like the colours on this shot.', '2008-12-15 14:46:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5132611, 747392, 100393, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2008-12-15 14:47:04.000000', NULL, 1),
(5132614, 746741, 100393, '<td valign="top">I was left looking at this for a while - always a good sign.</td>', 'I was left looking at this for a while - always a good sign.', '2008-12-15 14:47:35.000000', NULL, 1),
(5132616, 747458, 100393, '<td valign="top">Nicely lit and bang on brief.</td>', 'Nicely lit and bang on brief.', '2008-12-15 14:48:09.000000', NULL, 1),
(5132618, 747330, 100393, '<td valign="top">I really like this, but I think I would have cropped in a square - great lighting though, a 7 from me.</td>', 'I really like this, but I think I would have cropped in a square - great lighting though, a 7 from me.', '2008-12-15 14:49:10.000000', NULL, 1),
(5132620, 746908, 100393, '<td valign="top">Makes the eye hunt a bit - I really like it; it makes you feel as if you are actually outside - the snow looks like it is lit by a full moon.</td>', 'Makes the eye hunt a bit - I really like it; it makes you feel as if you are actually outside - the snow looks like it is lit by a full moon.', '2008-12-15 14:50:19.000000', NULL, 1),
(5132654, 747219, 55956, '<td valign="top">nice photo. I don''t know why but the actor with the black hat remember me the Doc of Back to the future. 8</td>', 'nice photo. I don''t know why but the actor with the black hat remember me the Doc of Back to the future. 8', '2008-12-15 15:00:58.000000', NULL, 1),
(5132688, 745820, 100393, '<td valign="top">This is a really nice image but it does look like its sharpness has been software induced; good though.</td>', 'This is a really nice image but it does look like its sharpness has been software induced; good though.', '2008-12-15 15:12:04.000000', NULL, 1),
(5132692, 747180, 100393, '<td valign="top">I really like this image; great focus and DOF and a really clean and simple composition.</td>', 'I really like this image; great focus and DOF and a really clean and simple composition.', '2008-12-15 15:14:19.000000', NULL, 1),
(5132695, 747162, 100393, '<td valign="top">I really like the whole day / night dichotomy here. Good job - 7.</td>', 'I really like the whole day / night dichotomy here. Good job - 7.', '2008-12-15 15:15:16.000000', NULL, 1),
(5132696, 747428, 100393, '<td valign="top">I really like the blue gradation on this image.</td>', 'I really like the blue gradation on this image.', '2008-12-15 15:16:11.000000', NULL, 1),
(5132698, 746715, 100393, '<td valign="top">This is a really unusual image - loads of depth to it. It holds the viewer much longer than most. Great job.</td>', 'This is a really unusual image - loads of depth to it. It holds the viewer much longer than most. Great job.', '2008-12-15 15:17:19.000000', NULL, 1),
(5132701, 747449, 100393, '<td valign="top">Perfect colours for this the composition - I love the angles too.<br/> <br/>I think you have captured the essence of the building (or at least I get that impression from what you have shown us!)</td>', 'Perfect colours for this the composition - I love the angles too. I think you have captured the essence of the building (or at least I get that impression from what you have shown us!)', '2008-12-15 15:18:46.000000', NULL, 1),
(5132704, 747474, 100393, '<td valign="top">This is really creative and very pretty.</td>', 'This is really creative and very pretty.', '2008-12-15 15:19:17.000000', NULL, 1),
(5132710, 747464, 100393, '<td valign="top">I''m normally not fond of starburst filters, but with this composition and with how ''in-your-face'' the effect is, I think it really works.</td>', 'I''m normally not fond of starburst filters, but with this composition and with how ''in-your-face'' the effect is, I think it really works.', '2008-12-15 15:21:05.000000', NULL, 1),
(5132712, 747461, 100393, '<td valign="top">I scored this a 7 on my first pass but I going through again with comments and this one has stopped me in my tracks. I love it - bumping up to a 9.</td>', 'I scored this a 7 on my first pass but I going through again with comments and this one has stopped me in my tracks. I love it - bumping up to a 9.', '2008-12-15 15:22:16.000000', NULL, 1),
(5132714, 745989, 100393, '<td valign="top">Subtle. Nice job.</td>', 'Subtle. Nice job.', '2008-12-15 15:22:48.000000', NULL, 1),
(5132717, 746672, 100393, '<td valign="top">I''m glad you had your title - it took me a while to see that it was on brief. However, star or no star - it''s a great shot.</td>', 'I''m glad you had your title - it took me a while to see that it was on brief. However, star or no star - it''s a great shot.', '2008-12-15 15:23:54.000000', NULL, 1),
(5132720, 747046, 100393, '<td valign="top">Technically, I think this is really good but its not an image I would want to keep looking at - 6.</td>', 'Technically, I think this is really good but its not an image I would want to keep looking at - 6.', '2008-12-15 15:24:41.000000', NULL, 1),
(5132722, 747290, 100393, '<td valign="top">This is clearly really competent but it is just a bit busy for my taste.</td>', 'This is clearly really competent but it is just a bit busy for my taste.', '2008-12-15 15:25:20.000000', NULL, 1),
(5132723, 747219, 100393, '<td valign="top">A different interpretation of the brief and a great picture.</td>', 'A different interpretation of the brief and a great picture.', '2008-12-15 15:25:53.000000', NULL, 1),
(5132725, 747452, 100393, '<td valign="top">The really short DOF works well here - you have shown us so much of the surface texture of the fruit, it feels like you could touch it.</td>', 'The really short DOF works well here - you have shown us so much of the surface texture of the fruit, it feels like you could touch it.', '2008-12-15 15:27:36.000000', NULL, 1),
(5132728, 747379, 100393, '<td valign="top">Nice composition, for me, I think a little more exposure would have added to its opulent feel.</td>', 'Nice composition, for me, I think a little more exposure would have added to its opulent feel.', '2008-12-15 15:28:37.000000', NULL, 1),
(5132734, 747081, 100393, '<td valign="top">Perfectly shot - great use of a short DOF, but a bit too simple to be really great.<br/> <br/>Probably the first shot I''ve seen where a border really works.</td>', 'Perfectly shot - great use of a short DOF, but a bit too simple to be really great. Probably the first shot I''ve seen where a border really works.', '2008-12-15 15:30:02.000000', NULL, 1),
(5132736, 747479, 100393, '<td valign="top">I can see this has been made deliberately soft - a nice image.</td>', 'I can see this has been made deliberately soft - a nice image.', '2008-12-15 15:30:48.000000', NULL, 1),
(5132824, 747453, 100393, '<td valign="top">You could have entered this for the Bokeh challenge too! Nice image</td>', 'You could have entered this for the Bokeh challenge too! Nice image', '2008-12-15 16:11:04.000000', NULL, 1),
(5132858, 747046, 43774, '<td valign="top">Cute title and a very good photo.</td>', 'Cute title and a very good photo.', '2008-12-15 16:47:06.000000', NULL, 1),
(5132892, 747170, 66952, '<td valign="top">The City and County building! I haven''t seen that since I was a kid.</td>', 'The City and County building! I haven''t seen that since I was a kid.', '2008-12-15 17:34:32.000000', NULL, 1),
(5132919, 747481, 38408, '<td valign="top">love the colour and light in this</td>', 'love the colour and light in this', '2008-12-15 18:07:23.000000', NULL, 1),
(5132946, 747158, 51793, '<td valign="top">I think this could have won the challenge if the colors were better and it was in focus. It''s a great idea but it could use come help.</td>', 'I think this could have won the challenge if the colors were better and it was in focus. It''s a great idea but it could use come help.', '2008-12-15 18:33:03.000000', NULL, 1),
(5132948, 746732, 51793, '<td valign="top">What a great idea, I like how you have all the cookies standing up.</td>', 'What a great idea, I like how you have all the cookies standing up.', '2008-12-15 18:34:03.000000', NULL, 1),
(5132976, 747175, 100393, '<td valign="top">I''ve no idea on the technicalities of astronomical photography - but the resultant image is very nice. I wonder how many stars there are here....?</td>', 'I''ve no idea on the technicalities of astronomical photography - but the resultant image is very nice. I wonder how many stars there are here....?', '2008-12-15 18:54:27.000000', NULL, 1),
(5132977, 747466, 100393, '<td valign="top">Bang on brief, nice colours and composition.</td>', 'Bang on brief, nice colours and composition.', '2008-12-15 18:54:55.000000', NULL, 1),
(5132980, 747484, 100393, '<td valign="top">Nice image - I particularly like the movement in the clouds.</td>', 'Nice image - I particularly like the movement in the clouds.', '2008-12-15 18:55:26.000000', NULL, 1),
(5132983, 746549, 100393, '<td valign="top">I went to give this an 8 but the blown highlights in the sky detract from what would have been a really great image. 6.</td>', 'I went to give this an 8 but the blown highlights in the sky detract from what would have been a really great image. 6.', '2008-12-15 18:57:35.000000', NULL, 1),
(5132984, 747356, 100393, '<td valign="top">Very nice, clean image. The star shaped shadow is particularly effective.</td>', 'Very nice, clean image. The star shaped shadow is particularly effective.', '2008-12-15 18:58:12.000000', NULL, 1),
(5132988, 747380, 100393, '<td valign="top">Nice high key shot - given how my image was received in the before and after challenge, many people may not have the monitor settings to get the most out of this image.</td>', 'Nice high key shot - given how my image was received in the before and after challenge, many people may not have the monitor settings to get the most out of this image.', '2008-12-15 18:59:46.000000', NULL, 1),
(5133202, 747306, 77196, '<td valign="top">You''re going to get pasted score wise, since monitors vary so much, and on many this looks like just a black square.</td>', 'You''re going to get pasted score wise, since monitors vary so much, and on many this looks like just a black square.', '2008-12-15 21:48:49.000000', NULL, 1),
(5133226, 747330, 99981, '<td valign="top">Great photo! I''m sorry i can''t vote in this challenge!</td>', 'Great photo! I''m sorry i can''t vote in this challenge!', '2008-12-15 21:58:50.000000', NULL, 1),
(5133244, 746741, 69046, '<td valign="top">Longs Peak, the Diamond?  Awesome exposure on the foreground mountains. Looks like daylight. You nailed it. 10</td>', 'Longs Peak, the Diamond?  Awesome exposure on the foreground mountains. Looks like daylight. You nailed it. 10', '2008-12-15 22:05:35.000000', NULL, 1),
(5133246, 747440, 96915, '<td valign="top">I love the composition, with both horses facing the camera at the same angle, and I think the whiskers are great!</td>', 'I love the composition, with both horses facing the camera at the same angle, and I think the whiskers are great!', '2008-12-15 22:06:23.000000', NULL, 1),
(5133248, 746825, 69046, '<td valign="top">Wow. 10</td>', 'Wow. 10', '2008-12-15 22:07:02.000000', NULL, 1),
(5133250, 747175, 69046, '<td valign="top">The real thing. Truly beautiful, 10</td>', 'The real thing. Truly beautiful, 10', '2008-12-15 22:07:47.000000', NULL, 1),
(5133255, 747484, 69046, '<td valign="top">Orion, beautiful colors. 10</td>', 'Orion, beautiful colors. 10', '2008-12-15 22:10:29.000000', NULL, 1),
(5133264, 747382, 24454, '<td valign="top">Auuuuuugh. . this is BEAUTIFUL!!!!   Perfect stars in those amazing lights and reflections.   I love this stunning photo!</td>', 'Auuuuuugh. . this is BEAUTIFUL!!!!   Perfect stars in those amazing lights and reflections.   I love this stunning photo!', '2008-12-15 22:13:47.000000', NULL, 1),
(5133267, 747170, 69046, '<td valign="top">Denver City Denver, love the exposure, you nailed it. Composition is a little static for around here, but I like it. Technically excellent.10</td>', 'Denver City Denver, love the exposure, you nailed it. Composition is a little static for around here, but I like it. Technically excellent.10', '2008-12-15 22:14:16.000000', NULL, 1),
(5133269, 746859, 69046, '<td valign="top">Sweet exposure. 10</td>', 'Sweet exposure. 10', '2008-12-15 22:14:54.000000', NULL, 1),
(5133271, 747481, 69046, '<td valign="top">Oh jeez, 10</td>', 'Oh jeez, 10', '2008-12-15 22:15:29.000000', NULL, 1),
(5133272, 747290, 24454, '<td valign="top">This is BEAUTIFUL!!!  I love urban photography, and this is a FINE one!  I love the abstract quality you have achieved without losing the magical quality of the lights and colors.  Good luck.  I think this is definitely one of the best here!</td>', 'This is BEAUTIFUL!!!  I love urban photography, and this is a FINE one!  I love the abstract quality you have achieved without losing the magical quality of the lights and colors.  Good luck.  I think this is definitely one of the best here!', '2008-12-15 22:15:39.000000', NULL, 1),
(5133275, 747137, 69046, '<td valign="top">Love it, 10</td>', 'Love it, 10', '2008-12-15 22:16:52.000000', NULL, 1),
(5133319, 747242, 66515, '<td valign="top">The focus of should be what''s inside the border and not the border itself. This border is really distracting for me.</td>', 'The focus of should be what''s inside the border and not the border itself. This border is really distracting for me.', '2008-12-15 23:08:09.000000', NULL, 1),
(5133357, 747235, 53814, '<td valign="top">a pleasure to see such art...</td>', 'a pleasure to see such art...', '2008-12-16 00:08:47.000000', NULL, 1),
(5133393, 747428, 15511, '<td valign="top">That is, when the planets align... ;&gt;)</td>', 'That is, when the planets align... ;>)', '2008-12-16 00:45:54.000000', NULL, 1),
(5133486, 746910, 100393, '<td valign="top">It''s a great photo - it won''t be everybody''s cup of tea for this challenge, but technically I think it is excellent.</td>', 'It''s a great photo - it won''t be everybody''s cup of tea for this challenge, but technically I think it is excellent.', '2008-12-16 03:05:33.000000', NULL, 1),
(5133487, 746859, 100393, '<td valign="top">Taken slightly to the left of the ''Night Reflections'' image by another photographer... I''ll assume a school project or something similar and try to score this image on its merits.<br/> <br/>I think the day / night dichotomy is the primary interest in this image and as such I don''t think you pull that off as well as the other image which captures that more interestingly. Otherwise I think the foreground composition is actually a little more interesting.</td>', 'Taken slightly to the left of the ''Night Reflections'' image by another photographer... I''ll assume a school project or something similar and try to score this image on its merits. I think the day / night dichotomy is the primary interest in this image and as such I don''t think you pull that off as well as the other image which captures that more interestingly. Otherwise I think the foreground composition is actually a little more interesting.', '2008-12-16 03:11:20.000000', NULL, 1),
(5133488, 747076, 100393, '<td valign="top">Simple but effective. The creases in the background are a little distracting but a nice image nonetheless.</td>', 'Simple but effective. The creases in the background are a little distracting but a nice image nonetheless.', '2008-12-16 03:12:10.000000', NULL, 1),
(5133490, 747446, 100393, '<td valign="top">Great bokeh! I think the central star could be a tad brighter but the background is really great.</td>', 'Great bokeh! I think the central star could be a tad brighter but the background is really great.', '2008-12-16 03:13:21.000000', NULL, 1),
(5133491, 747167, 100393, '<td valign="top">An interesting image - I have no experience in this sort of photography so I don''t know how this compares to what is possible.</td>', 'An interesting image - I have no experience in this sort of photography so I don''t know how this compares to what is possible.', '2008-12-16 03:14:27.000000', NULL, 1),
(5133492, 746968, 100393, '<td valign="top">This is one of those images that looks better the more you looking at it - bumping it up from a 6 to a 7.</td>', 'This is one of those images that looks better the more you looking at it - bumping it up from a 6 to a 7.', '2008-12-16 03:15:16.000000', NULL, 1),
(5133494, 747242, 100393, '<td valign="top">Nice shot. For me, I would''ve like to have either seen a bit more of the background or have pushed up the black point to obliterate it completely. The fact that is is just visible but nly in places is a bit distracting to the eye. 6.</td>', 'Nice shot. For me, I would''ve like to have either seen a bit more of the background or have pushed up the black point to obliterate it completely. The fact that is is just visible but nly in places is a bit distracting to the eye. 6.', '2008-12-16 03:17:15.000000', NULL, 1),
(5133495, 747475, 100393, '<td valign="top">Nice and simple - I really like the way you have nested the cutters and not been tempted to have them completely central to one another.</td>', 'Nice and simple - I really like the way you have nested the cutters and not been tempted to have them completely central to one another.', '2008-12-16 03:18:29.000000', NULL, 1),
(5133496, 747182, 100393, '<td valign="top">I like the perspective and angles here .</td>', 'I like the perspective and angles here .', '2008-12-16 03:19:09.000000', NULL, 1),
(5133497, 746165, 100393, '<td valign="top">Clearly a very good portrait shot - some won''t like your interpretation of the brief but a nice shot nonetheless.</td>', 'Clearly a very good portrait shot - some won''t like your interpretation of the brief but a nice shot nonetheless.', '2008-12-16 03:20:01.000000', NULL, 1),
(5133498, 747472, 100393, '<td valign="top">Interesting image.</td>', 'Interesting image.', '2008-12-16 03:20:37.000000', NULL, 1),
(5133500, 747309, 100393, '<td valign="top">SInce there isn''t any form of star in the picture, I''m sure this will cost you in scoring.<br/> <br/>It is a nice picture of the moon, but for me its interest level is a little limited.</td>', 'SInce there isn''t any form of star in the picture, I''m sure this will cost you in scoring. It is a nice picture of the moon, but for me its interest level is a little limited.', '2008-12-16 03:22:14.000000', NULL, 1),
(5133504, 747027, 100393, '<td valign="top">Interesting building and shot - for me, I think I would have played with the colour temperature a little and emphasised the blue even more. I think leaving the adjacent buildings within the shot makes this one stand out - I would have tried to push that a little further for effect.<br/> <br/>I like it though - it makes me want to go into the shop!</td>', 'Interesting building and shot - for me, I think I would have played with the colour temperature a little and emphasised the blue even more. I think leaving the adjacent buildings within the shot makes this one stand out - I would have tried to push that a little further for effect. I like it though - it makes me want to go into the shop!', '2008-12-16 03:24:22.000000', NULL, 1),
(5133506, 747382, 100393, '<td valign="top">This is a nice shot with a great reflection, but otherwise I think the interest level falls a little short for me. I wonder how it would have looked angled, with the left hand side of the bridge intersecting with the lower left corner of the image.</td>', 'This is a nice shot with a great reflection, but otherwise I think the interest level falls a little short for me. I wonder how it would have looked angled, with the left hand side of the bridge intersecting with the lower left corner of the image.', '2008-12-16 03:26:17.000000', NULL, 1),
(5133508, 746058, 100393, '<td valign="top">Some won''t like your interpretation of the brief, but this is a nice and unusual portrait.</td>', 'Some won''t like your interpretation of the brief, but this is a nice and unusual portrait.', '2008-12-16 03:27:01.000000', NULL, 1),
(5133512, 747124, 100393, '<td valign="top">Very simple composition - I love the splash. Given the yellow on blue contrast is a central feature of the image, I think I would have given a bit more saturation of those colours - but then I''m not very subtle!</td>', 'Very simple composition - I love the splash. Given the yellow on blue contrast is a central feature of the image, I think I would have given a bit more saturation of those colours - but then I''m not very subtle!', '2008-12-16 03:28:44.000000', NULL, 1),
(5133514, 747500, 100393, '<td valign="top">Nice image but I think this sort of shot demands nothing less than absolute sharpness and clarity - this one isn''t quite there.</td>', 'Nice image but I think this sort of shot demands nothing less than absolute sharpness and clarity - this one isn''t quite there.', '2008-12-16 03:29:39.000000', NULL, 1),
(5133515, 747367, 100393, '<td valign="top">Very interesting subject but the the lighting makes it all seem a bit too flat.</td>', 'Very interesting subject but the the lighting makes it all seem a bit too flat.', '2008-12-16 03:30:27.000000', NULL, 1),
(5133617, 746719, 54446, '<td valign="top">Great sports capture.  I think this meets the challenge well, without showing any literal stars.  I didn''t even need to read the title to understand.  My favorite in this challenge.  (10)</td>', 'Great sports capture.  I think this meets the challenge well, without showing any literal stars.  I didn''t even need to read the title to understand.  My favorite in this challenge.  (10)', '2008-12-16 05:16:49.000000', NULL, 1),
(5133619, 747175, 54446, '<td valign="top">Outstanding astrophotography, I think.  A joy to view.  (9)</td>', 'Outstanding astrophotography, I think.  A joy to view.  (9)', '2008-12-16 05:17:00.000000', NULL, 1),
(5133621, 747469, 54446, '<td valign="top">A very eye-pleasing image.  (9)</td>', 'A very eye-pleasing image.  (9)', '2008-12-16 05:17:15.000000', NULL, 1),
(5133624, 745678, 54446, '<td valign="top">While I like the fantasy concept, the artificial "look" of the homogeneous stars, in front of the clouds, is a major distraction for me. (7)</td>', 'While I like the fantasy concept, the artificial "look" of the homogeneous stars, in front of the clouds, is a major distraction for me. (7)', '2008-12-16 05:19:08.000000', NULL, 1),
(5133627, 746968, 54446, '<td valign="top">A beautiful scene.  Just improbable in real life... to see stars around a full moon.  Yes, I understand you can combine frames, so I didn''t deduct any score for the distraction.</td>', 'A beautiful scene.  Just improbable in real life... to see stars around a full moon.  Yes, I understand you can combine frames, so I didn''t deduct any score for the distraction.', '2008-12-16 05:23:49.000000', NULL, 1),
(5133628, 747484, 54446, '<td valign="top">Very nice Orion constellation.  I like the window view through the windswept clouds, too.  (8)</td>', 'Very nice Orion constellation.  I like the window view through the windswept clouds, too.  (8)', '2008-12-16 05:26:23.000000', NULL, 1),
(5133629, 746672, 54446, '<td valign="top">Just gorgeous seascape.  Nice job on the one star, too.  Bumping up on final review. (10)</td>', 'Just gorgeous seascape.  Nice job on the one star, too.  Bumping up on final review. (10)', '2008-12-16 05:27:21.000000', NULL, 1),
(5133701, 747454, 63141, '<td valign="top">very srong picture</td>', 'very srong picture', '2008-12-16 06:55:10.000000', NULL, 1),
(5133822, 747481, 60047, '<td valign="top">I love the colors and the design. Noticeably darker than I would have expected - but this has enriched the color tones positively. The shadows in the bottom third of the photo are the only criticism I can point to being a detraction.</td>', 'I love the colors and the design. Noticeably darker than I would have expected - but this has enriched the color tones positively. The shadows in the bottom third of the photo are the only criticism I can point to being a detraction.', '2008-12-16 08:21:35.000000', NULL, 1),
(5133823, 747175, 60047, '<td valign="top">Truly stunning.</td>', 'Truly stunning.', '2008-12-16 08:22:01.000000', NULL, 1),
(5133826, 747170, 60047, '<td valign="top">Fantastic shot. Beautiful colors, here.</td>', 'Fantastic shot. Beautiful colors, here.', '2008-12-16 08:22:58.000000', NULL, 1),
(5133829, 746825, 60047, '<td valign="top">Captivating - an unexpected answer to the challenge. Quite well done.</td>', 'Captivating - an unexpected answer to the challenge. Quite well done.', '2008-12-16 08:23:52.000000', NULL, 1),
(5133832, 747444, 60047, '<td valign="top">Gorgeous. Beautiful capture.</td>', 'Gorgeous. Beautiful capture.', '2008-12-16 08:24:15.000000', NULL, 1),
(5133834, 745989, 60047, '<td valign="top">Great concept. Excellent execution.</td>', 'Great concept. Excellent execution.', '2008-12-16 08:24:46.000000', NULL, 1),
(5133837, 747242, 60047, '<td valign="top">Simple and elegant. The border really compliments this shot and dresses it up beautifully.</td>', 'Simple and elegant. The border really compliments this shot and dresses it up beautifully.', '2008-12-16 08:25:50.000000', NULL, 1),
(5133841, 747474, 60047, '<td valign="top">I really like this shot. I think the color combination is classically festive and elegant.</td>', 'I really like this shot. I think the color combination is classically festive and elegant.', '2008-12-16 08:26:39.000000', NULL, 1),
(5133842, 745908, 60047, '<td valign="top">I love the colors captured here. I really wish this was sharper.</td>', 'I love the colors captured here. I really wish this was sharper.', '2008-12-16 08:27:37.000000', NULL, 1),
