(5135160, 746908, 97225, '<td valign="top">Beautiful shot. It looks soooo cold. How can you go out and take photos? 9</td>', 'Beautiful shot. It looks soooo cold. How can you go out and take photos? 9', '2008-12-16 17:53:51.000000', NULL, 1),
