(5135166, 747483, 97225, '<td valign="top">Beautiful star. I love the colours in it.</td>', 'Beautiful star. I love the colours in it.', '2008-12-16 17:56:19.000000', NULL, 1),
(5135167, 747444, 97225, '<td valign="top">Fabulous shot, and I love your title. 10</td>', 'Fabulous shot, and I love your title. 10', '2008-12-16 17:57:23.000000', NULL, 1),
