(5135170, 747137, 97225, '<td valign="top">Nicely processed.</td>', 'Nicely processed.', '2008-12-16 17:58:45.000000', NULL, 1),
(5135171, 746549, 97225, '<td valign="top">Beautiful shot and excellent exposure.</td>', 'Beautiful shot and excellent exposure.', '2008-12-16 17:59:18.000000', NULL, 1),
(5135172, 746968, 97225, '<td valign="top">Lovely shot.</td>', 'Lovely shot.', '2008-12-16 17:59:48.000000', NULL, 1),
(5135173, 747481, 97225, '<td valign="top">This is beautiful, and I think that you must have gone to a fair bit of effort to set this up.</td>', 'This is beautiful, and I think that you must have gone to a fair bit of effort to set this up.', '2008-12-16 18:01:31.000000', NULL, 1),
(5135176, 745989, 97225, '<td valign="top">Lovely shot. Interesting catch light.</td>', 'Lovely shot. Interesting catch light.', '2008-12-16 18:03:19.000000', NULL, 1),
(5135177, 747046, 97225, '<td valign="top">Excellent effect.</td>', 'Excellent effect.', '2008-12-16 18:04:06.000000', NULL, 1),
(5135178, 746343, 97225, '<td valign="top">Beautiful starbursts. This would be a great Christmas card.</td>', 'Beautiful starbursts. This would be a great Christmas card.', '2008-12-16 18:05:01.000000', NULL, 1),
(5135181, 747071, 97225, '<td valign="top">Beautiful shot. Lovely capture of the sun and I love the light on the spray.</td>', 'Beautiful shot. Lovely capture of the sun and I love the light on the spray.', '2008-12-16 18:07:03.000000', NULL, 1),
(5135183, 747453, 97225, '<td valign="top">That is cool.</td>', 'That is cool.', '2008-12-16 18:08:03.000000', NULL, 1),
(5135209, 747454, 97225, '<td valign="top">Peace on Earth and goodwill to all men..... We can only hope that this will be so. This picture is a confrontational reminder that it isn''t always so, and that sometimes it isn''t to a staggering degree. May lessons from the past never be forgotten.</td>', 'Peace on Earth and goodwill to all men..... We can only hope that this will be so. This picture is a confrontational reminder that it isn''t always so, and that sometimes it isn''t to a staggering degree. May lessons from the past never be forgotten.', '2008-12-16 18:26:12.000000', NULL, 1),
(5135211, 747124, 97225, '<td valign="top">I love the little bow wave.</td>', 'I love the little bow wave.', '2008-12-16 18:26:44.000000', NULL, 1),
(5135213, 747330, 97225, '<td valign="top">Best of the starfruit entries. The light and colour are gorgeous.</td>', 'Best of the starfruit entries. The light and colour are gorgeous.', '2008-12-16 18:27:32.000000', NULL, 1),
(5135219, 746910, 97225, '<td valign="top">Omg! Not in my neighbourhood I hope. Great job with the shot.</td>', 'Omg! Not in my neighbourhood I hope. Great job with the shot.', '2008-12-16 18:29:18.000000', NULL, 1),
(5135221, 746856, 97225, '<td valign="top">Nice processing.</td>', 'Nice processing.', '2008-12-16 18:29:47.000000', NULL, 1),
(5135226, 747271, 97225, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2008-12-16 18:30:30.000000', NULL, 1),
(5135227, 747384, 97225, '<td valign="top">Nice arrangement, well photographed.</td>', 'Nice arrangement, well photographed.', '2008-12-16 18:31:03.000000', NULL, 1),
(5135230, 747365, 97225, '<td valign="top">I think that possibly you could have made more use of the invisibility of the black threads against the black background with a change in hand position.</td>', 'I think that possibly you could have made more use of the invisibility of the black threads against the black background with a change in hand position.', '2008-12-16 18:33:51.000000', NULL, 1),
(5135233, 747309, 97225, '<td valign="top">Excellent clear moon shot.</td>', 'Excellent clear moon shot.', '2008-12-16 18:35:52.000000', NULL, 1),
(5135252, 747312, 100393, '<td valign="top">This is a nice vibrant image but some of the highlights are just a bit blown. That doesn''t detract too much though.</td>', 'This is a nice vibrant image but some of the highlights are just a bit blown. That doesn''t detract too much though.', '2008-12-16 18:49:43.000000', NULL, 1),
(5135254, 747439, 100393, '<td valign="top">Nice, simple composition - I like the subtle shadow.</td>', 'Nice, simple composition - I like the subtle shadow.', '2008-12-16 18:50:23.000000', NULL, 1),
(5135255, 747483, 100393, '<td valign="top">Great bokeh! And a nice image too.</td>', 'Great bokeh! And a nice image too.', '2008-12-16 18:50:54.000000', NULL, 1),
(5135257, 747302, 100393, '<td valign="top">Interesting image, great DOF choice.</td>', 'Interesting image, great DOF choice.', '2008-12-16 18:51:21.000000', NULL, 1),
(5135258, 747071, 100393, '<td valign="top">A nice image but a bit of a strange choice given that we have just had the sunset / sunrise challenge.</td>', 'A nice image but a bit of a strange choice given that we have just had the sunset / sunrise challenge.', '2008-12-16 18:51:58.000000', NULL, 1),
(5135261, 746856, 100393, '<td valign="top">This looks like one of those wax scratch art kits! Was that your intention? Very strong image but will probably be a bit too ''digital art'' for many.</td>', 'This looks like one of those wax scratch art kits! Was that your intention? Very strong image but will probably be a bit too ''digital art'' for many.', '2008-12-16 18:53:29.000000', NULL, 1),
(5135263, 747271, 100393, '<td valign="top">Quite a good image, but given the glasses are so prominent, I think it would have been better had the model been making eyes contact.</td>', 'Quite a good image, but given the glasses are so prominent, I think it would have been better had the model been making eyes contact.', '2008-12-16 18:54:23.000000', NULL, 1),
(5135266, 747341, 100393, '<td valign="top">I like the concept, but there is something about this image which doesn''t quite deliver. I can''t help thinking ''if only the bauble had been a brighter colour.''</td>', 'I like the concept, but there is something about this image which doesn''t quite deliver. I can''t help thinking ''if only the bauble had been a brighter colour.''', '2008-12-16 18:55:34.000000', NULL, 1),
(5135269, 745678, 100393, '<td valign="top">These stars look so evenly spaced that they look artificial. I think the foreground focus is a bit problematical - it''s neither really in or out of focus. Wonderful colours though.</td>', 'These stars look so evenly spaced that they look artificial. I think the foreground focus is a bit problematical - it''s neither really in or out of focus. Wonderful colours though.', '2008-12-16 18:57:34.000000', NULL, 1),
(5135270, 747384, 100393, '<td valign="top">Nice image but there probably isn''t that much too interest the eye - which is rather rich coming from me given my last submission to a challenge!</td>', 'Nice image but there probably isn''t that much too interest the eye - which is rather rich coming from me given my last submission to a challenge!', '2008-12-16 18:58:35.000000', NULL, 1),
(5135277, 747348, 100393, '<td valign="top">Could have been in this week''s bokeh challenge. Personally, I would have liked at least something to be in focus.</td>', 'Could have been in this week''s bokeh challenge. Personally, I would have liked at least something to be in focus.', '2008-12-16 18:59:37.000000', NULL, 1),
(5135278, 747385, 100393, '<td valign="top">A really interesting picture which pushes the boundaries of the brief.</td>', 'A really interesting picture which pushes the boundaries of the brief.', '2008-12-16 19:00:07.000000', NULL, 1),
(5135279, 747461, 93543, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2008-12-16 19:00:21.000000', NULL, 1),
(5135281, 747345, 100393, '<td valign="top">Quite a nice image but the crop, the focus and the choice of subject are all only nearly on the button for me.</td>', 'Quite a nice image but the crop, the focus and the choice of subject are all only nearly on the button for me.', '2008-12-16 19:01:15.000000', NULL, 1),
(5135284, 747469, 100393, '<td valign="top">Nice concept but I think this image is crying out for at least one element to be in sharp focus - if only to emphasise the bokeh of the rest of the image.</td>', 'Nice concept but I think this image is crying out for at least one element to be in sharp focus - if only to emphasise the bokeh of the rest of the image.', '2008-12-16 19:02:43.000000', NULL, 1),
(5135288, 747365, 100393, '<td valign="top">If I''m honest I''m not really keen on this image - I like the concept but there looks to be a number of ways you could have shot this subject. for me, it doesn''t look as if this image makes the most of the potential there is in this scene.</td>', 'If I''m honest I''m not really keen on this image - I like the concept but there looks to be a number of ways you could have shot this subject. for me, it doesn''t look as if this image makes the most of the potential there is in this scene.', '2008-12-16 19:05:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5135290, 747460, 100393, '<td valign="top">A nice image but I think it lacks enough ''wow factor'' to live with a lot of the competition in this challenge.</td>', 'A nice image but I think it lacks enough ''wow factor'' to live with a lot of the competition in this challenge.', '2008-12-16 19:05:55.000000', NULL, 1),
(5135293, 746719, 100393, '<td valign="top">A great punch and not a bad photo either! It certainly meets one interpretation of the brief - but I can''t imagine it will be that well received.</td>', 'A great punch and not a bad photo either! It certainly meets one interpretation of the brief - but I can''t imagine it will be that well received.', '2008-12-16 19:07:09.000000', NULL, 1),
(5135296, 747170, 100393, '<td valign="top">The colours are really nice here, but I think it would have been better had you included the base of the building. Was it obscured in some way?</td>', 'The colours are really nice here, but I think it would have been better had you included the base of the building. Was it obscured in some way?', '2008-12-16 19:08:15.000000', NULL, 1),
(5135297, 745908, 100393, '<td valign="top">I do like this image - it takes a while to find the point of focus, but when you do, it becomes a very rewarding image.</td>', 'I do like this image - it takes a while to find the point of focus, but when you do, it becomes a very rewarding image.', '2008-12-16 19:09:24.000000', NULL, 1),
(5135300, 747437, 100393, '<td valign="top">Quite a nice image but the composition doesn''t frame too much of interest.</td>', 'Quite a nice image but the composition doesn''t frame too much of interest.', '2008-12-16 19:09:57.000000', NULL, 1),
(5135306, 747440, 100393, '<td valign="top">A nice image which fulfills one interpretation of the brief. I think a ''letterbox'' crop may have been more effective.</td>', 'A nice image which fulfills one interpretation of the brief. I think a ''letterbox'' crop may have been more effective.', '2008-12-16 19:11:17.000000', NULL, 1),
(5135309, 747450, 100393, '<td valign="top">An OK image but I think it fails a bit on the ''interesting'' front.</td>', 'An OK image but I think it fails a bit on the ''interesting'' front.', '2008-12-16 19:11:54.000000', NULL, 1),
(5135313, 747230, 100393, '<td valign="top">An OK picture but an uninspiring subject for this challenge. I think a less vanilla angle and a creative choice of exposure and DOF might have offered a lot more interest. This just looks a bit ''point-and-shoot'' to me.</td>', 'An OK picture but an uninspiring subject for this challenge. I think a less vanilla angle and a creative choice of exposure and DOF might have offered a lot more interest. This just looks a bit ''point-and-shoot'' to me.', '2008-12-16 19:13:19.000000', NULL, 1),
(5135317, 747485, 100393, '<td valign="top">Not a bad image and it certainly fulfills the brief; it''s just not that interesting to look at though.</td>', 'Not a bad image and it certainly fulfills the brief; it''s just not that interesting to look at though.', '2008-12-16 19:14:07.000000', NULL, 1),
(5135318, 747070, 100393, '<td valign="top">An OK image but I think a more creative angle and exposure would have improved it greatly.</td>', 'An OK image but I think a more creative angle and exposure would have improved it greatly.', '2008-12-16 19:14:49.000000', NULL, 1),
(5135319, 747158, 100393, '<td valign="top">Quite a nice composition but I think an image like this needs the central subject to be perfectly sharp to be truly effective.</td>', 'Quite a nice composition but I think an image like this needs the central subject to be perfectly sharp to be truly effective.', '2008-12-16 19:15:50.000000', NULL, 1),
(5135323, 746938, 100393, '<td valign="top">I am struggling to see how this fits the brief - but I guess the musician is a ''star''. The image doesn''t have a lot to hold a viewers interest for very long - at least not mine anyway.</td>', 'I am struggling to see how this fits the brief - but I guess the musician is a ''star''. The image doesn''t have a lot to hold a viewers interest for very long - at least not mine anyway.', '2008-12-16 19:17:16.000000', NULL, 1),
(5135326, 746239, 100393, '<td valign="top">I think perhaps a title like ''Seeing Stars'' might have been more fitting. Interesting effect but I don''t think this image will be very well received.</td>', 'I think perhaps a title like ''Seeing Stars'' might have been more fitting. Interesting effect but I don''t think this image will be very well received.', '2008-12-16 19:18:22.000000', NULL, 1),
(5135330, 747454, 100393, '<td valign="top">Obviously the concept is clear and you weren''t going for an attractive image, but I don''t think the image does the concept justice on any level.</td>', 'Obviously the concept is clear and you weren''t going for an attractive image, but I don''t think the image does the concept justice on any level.', '2008-12-16 19:20:16.000000', NULL, 1),
(5135331, 747499, 100393, '<td valign="top">Hmm... stars to the Nth degree. A bit to busy for me and the whole effect looks a bit ''point-and-shoot'' for me.</td>', 'Hmm... stars to the Nth degree. A bit to busy for me and the whole effect looks a bit ''point-and-shoot'' for me.', '2008-12-16 19:21:13.000000', NULL, 1),
(5135335, 747306, 100393, '<td valign="top">Does what is says on the tin but I don''t think this image can live with the competition in this challenge.</td>', 'Does what is says on the tin but I don''t think this image can live with the competition in this challenge.', '2008-12-16 19:22:13.000000', NULL, 1),
(5135336, 747214, 100393, '<td valign="top">An OK image, but the partial tree isn''t working for me.</td>', 'An OK image, but the partial tree isn''t working for me.', '2008-12-16 19:22:51.000000', NULL, 1),
(5135337, 746343, 100393, '<td valign="top">AN OK image but the partial tree isn''t working for me - overall this looks a bit too ''point-and-shoot''.</td>', 'AN OK image but the partial tree isn''t working for me - overall this looks a bit too ''point-and-shoot''.', '2008-12-16 19:23:32.000000', NULL, 1),
(5135361, 747380, 2553, '<td valign="top">Risky, risky going with something so very hi-key.  I absolutely love it - nicely done subtle representation of star.</td>', 'Risky, risky going with something so very hi-key.  I absolutely love it - nicely done subtle representation of star.', '2008-12-16 19:44:57.000000', NULL, 1),
(5135367, 747382, 2553, '<td valign="top">I really like the overall tone of this image, and the beautiful lights.  I find the tree somewhat distracting and would have been tempted to crop it out - I find that I really want to focus on the bridge and lights.</td>', 'I really like the overall tone of this image, and the beautiful lights.  I find the tree somewhat distracting and would have been tempted to crop it out - I find that I really want to focus on the bridge and lights.', '2008-12-16 19:47:59.000000', NULL, 1),
(5135369, 747027, 2553, '<td valign="top">I love this delightful scene.  Very Christmas-y - looks like it should be a postcard.</td>', 'I love this delightful scene.  Very Christmas-y - looks like it should be a postcard.', '2008-12-16 19:48:30.000000', NULL, 1),
(5135370, 747481, 2553, '<td valign="top">BEE-U-TEE-FUL.</td>', 'BEE-U-TEE-FUL.', '2008-12-16 19:48:57.000000', NULL, 1),
(5135396, 747450, 67152, '<td valign="top">the choice to fill the frame works pretty well - the colors are nice and bright - the subject doesn''t have a lot of holding power</td>', 'the choice to fill the frame works pretty well - the colors are nice and bright - the subject doesn''t have a lot of holding power', '2008-12-16 20:05:43.000000', NULL, 1),
(5135398, 747382, 67152, '<td valign="top">pretty scene - i can empathize with cloudy skies when trying to shoot stars</td>', 'pretty scene - i can empathize with cloudy skies when trying to shoot stars', '2008-12-16 20:06:46.000000', NULL, 1),
(5135399, 747312, 67152, '<td valign="top">nice high contrast image - the lighting really works well to emphasize the shape</td>', 'nice high contrast image - the lighting really works well to emphasize the shape', '2008-12-16 20:07:45.000000', NULL, 1),
