(5141137, 747219, 30982, '<td valign="top">Too fun!!  Excellent idea for the challenge and very nice use of the light you had - well processed.</td>', 'Too fun!!  Excellent idea for the challenge and very nice use of the light you had - well processed.', '2008-12-19 15:21:55.000000', NULL, 1),
(5141138, 747444, 30982, '<td valign="top">Way cool idea and a fun picture!</td>', 'Way cool idea and a fun picture!', '2008-12-19 15:22:08.000000', NULL, 1),
